+package com.example;
+
+import com.microsoft.playwright.BrowserType;
+import com.microsoft.playwright.Playwright;
+import com.microsoft.playwright.options.AriaRole;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.web.server.LocalServerPort;
+
+import java.util.Map;
+
+import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
+
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT,
+        properties = "vaadin.launch-browser=false")
+class ContactBrowserTest {
+    @LocalServerPort
+    int port;
+
+    @Test
+    void typingSendingAndNavigationWorkInChromium() {
+        try (var playwright = Playwright.create(new Playwright.CreateOptions()
+                .setEnv(Map.of("PLAYWRIGHT_SKIP_BROWSER_DOWNLOAD", "1")));
+             var browser = playwright.chromium().launch(new BrowserType.LaunchOptions()
+                     .setHeadless(true).setArgs(java.util.List.of("--no-sandbox")))) {
+            var page = browser.newPage();
+            page.navigate("http://localhost:" + port + "/contact");
+            var send = page.getByRole(AriaRole.BUTTON,
+                    new com.microsoft.playwright.Page.GetByRoleOptions().setName("Send").setExact(true));
+            assertThat(send).isEnabled();
+            send.click();
+            assertThat(page.locator("vaadin-text-field").first()).hasAttribute("invalid", "");
+            page.getByLabel("Name", new com.microsoft.playwright.Page.GetByLabelOptions().setExact(true)).fill("Ada");
+            page.getByLabel("Phone", new com.microsoft.playwright.Page.GetByLabelOptions().setExact(true)).fill("123");
+            var message = page.getByLabel("Message", new com.microsoft.playwright.Page.GetByLabelOptions().setExact(true));
+            message.fill("Hello from Chromium");
+            message.press("Enter");
+            assertThat(send).isDisabled();
+            assertThat(page.locator("vaadin-grid")).containsText("Hello from Chromium");
+            assertThat(message).isEmpty();
+            page.getByLabel("Email", new com.microsoft.playwright.Page.GetByLabelOptions().setExact(true)).fill("draft@example.com");
+            assertThat(send).isEnabled();
+            page.getByRole(AriaRole.LINK, new com.microsoft.playwright.Page.GetByRoleOptions().setName("About")).click();
+            page.getByRole(AriaRole.BUTTON, new com.microsoft.playwright.Page.GetByRoleOptions().setName("Keep editing")).click();
+            assertThat(page).hasURL("http://localhost:" + port + "/contact");
+            assertThat(page.getByLabel("Email", new com.microsoft.playwright.Page.GetByLabelOptions().setExact(true))).hasValue("draft@example.com");
+            page.getByRole(AriaRole.LINK, new com.microsoft.playwright.Page.GetByRoleOptions().setName("About")).click();
+            page.getByRole(AriaRole.BUTTON, new com.microsoft.playwright.Page.GetByRoleOptions().setName("Discard")).click();
+            assertThat(page.locator("h1")).hasText("About");
+            page.navigate("http://localhost:" + port + "/contact");
+            assertThat(page.locator("vaadin-grid")).containsText("Hello from Chromium");
+        }
+    }
+}
